def solve(record):
    try:
        x = record['record_2']
    except (KeyError, TypeError):
        return None
    if not isinstance(x, (list, tuple)) or len(x) < 3:
        return None
    edges, source, target = x[0], x[1], x[2]
    graph = {}
    for e in edges or []:
        try:
            u, v = e[0], e[1]
        except (TypeError, ValueError, IndexError):
            continue
        graph.setdefault(u, set()).add(v)
        graph.setdefault(v, set())
    if source not in graph:
        graph[source] = set()
    if target not in graph:
        graph[target] = set()

    from collections import deque
    if source != target:
        dist = {source: 0}
        q = deque([source])
        while q:
            cur = q.popleft()
            for nxt in graph.get(cur, ()):
                if nxt == target:
                    return dist[cur] + 1
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    q.append(nxt)
        return None
