def solve(record):
    """
    Build a histogram over observed integer readings.

    Contract:
      - The input payload is read from record['record_1'].
      - Negative readings indicate a sensor fault and are discarded.
      - Each distinct valid reading becomes a bin.
      - All recorded bins are published, ordered by first observation.
      - Returns a list of [value, count] pairs; empty input returns [].

    No external tools or files are used; only native Python data structures.
    """
    readings = record.get("record_1") or []

    counts = {}
    order = []

    for raw in readings:
        value = _coerce_int(raw)
        if value is None:
            # Not a usable reading; ignore noise so it does not affect bins.
            continue
        if value < 0:
            # Negative readings mark a sensor fault and are excluded.
            continue
        if value not in counts:
            counts[value] = 0
            order.append(value)
        counts[value] += 1

    return [[value, counts[value]] for value in order]

def _coerce_int(raw):
    # Only accept exact integers or string forms that clearly represent them.
    if isinstance(raw, bool):
        return None
    if isinstance(raw, int):
        return raw
    if isinstance(raw, str):
        text = raw.strip()
        if text and (text.isdigit() or (text[0] in "+-" and text[1:].isdigit())):
            return int(text)
    return None

