def solve(record):
    """
    Build a histogram of observed integer readings.

    - Input comes from record['record_1'], which may be a list/tuple of values
      or a string containing whitespace/comma separated numbers.
    - Readings are interpreted as integers where possible.
    - Negative readings represent sensor faults and are discarded.
    - Output is a list of [value, count] pairs sorted by value ascending.
    - An empty or invalid input yields [].
    """
    readings = []

    def _extract_numbers(value):
        # Recursively pull numeric-looking tokens out of common payload shapes.
        if value is None:
            return
        if isinstance(value, bool):
            return
        if isinstance(value, (int, float)):
            readings.append(value)
            return
        if isinstance(value, str):
            token = value.strip()
            if token:
                try:
                    readings.append(float(token))
                except ValueError:
                    pass
            return
        if isinstance(value, dict):
            for key in ('record_1', 'value', 'reading', 'x', 'data', 'readings', 'values'):
                if key in value:
                    _extract_numbers(value[key])
            return
        if isinstance(value, (list, tuple, set, frozenset)):
            for item in value:
                _extract_numbers(item)
            return
        # Fallback: try a generic string conversion for objects with str repr of a number
        try:
            readings.append(float(value))
        except (TypeError, ValueError):
            pass

    raw = None
    if record is not None:
        if isinstance(record, dict):
            raw = record.get('record_1')
        else:
            raw = record
    _extract_numbers(raw)

    counts = {}
    for value in readings:
        try:
            iv = int(value)
        except (TypeError, ValueError, OverflowError):
            continue
        if iv < 0:
            # Negative readings are treated as sensor faults and ignored.
            continue
        counts[iv] = counts.get(iv, 0) + 1

    return [[v, counts[v]] for v in sorted(counts)]
