        return -1
    graph = defaultdict(list)
    try:
        for edge in edges:
            u, v = edge[0], edge[1]
            graph[u].append(v)
    except Exception:
        pass
    dist = {source: 0}
    queue = deque([source])
    same = (source == target)
    while queue:
        u = queue.popleft()
        d = dist.get(u, -1)
        if not same and u == target:
