def solve(record):
    """
    Convert a dense list of signed integers into sparse [index, value] rows.

    - Input is taken from record['record_2'].
    - record_2 may be a list of ints, or a string containing comma-separated ints.
    - A zero value produces no row.
    - Indices are zero-based memory offsets visited in ascending order.
    - Both positive and negative values are preserved.
    - record_2 == [] or None returns [].
    """
    def _coerce(v):
        # Convert a single token to int, tolerating whitespace and +/- signs.
        try:
            return int(str(v).strip())
        except (TypeError, ValueError):
            return None

    def _parse_input(raw):
        if raw is None:
            return []
        if isinstance(raw, str):
            cleaned = raw.strip()
            if not cleaned:
                return []
            cleaned = cleaned.strip("[]")
            parts = cleaned.split(",") if "," in cleaned else cleaned.split()
            vals = []
            for p in parts:
                p = p.strip()
                if not p:
                    continue
                n = _coerce(p)
                if n is None:
                    # tolerate floats written as strings by truncating toward zero
                    try:
                        n = int(float(p))
                    except (TypeError, ValueError):
                        continue
                vals.append(n)
            return vals
        if isinstance(raw, (list, tuple)):
            vals = []
            for item in raw:
                n = _coerce(item)
                if n is None:
                    try:
                        n = int(float(item))
                    except (TypeError, ValueError):
                        continue
                vals.append(n)
            return vals
        # Single scalar fallback
        n = _coerce(raw)
        return [] if n is None else [n]

    x = record.get("record_2") if isinstance(record, dict) else None
    values = _parse_input(x)

    rows = []
    for offset, value in enumerate(values):
        if value != 0:
            rows.append([offset, value])
    return rows

