def solve(record):
    """
    Rotate the list in record['record_3'] by k positions.

    - record['record_3'] is [k, values]
    - k is a nonnegative integer number of positions to rotate
    - each distinct ID occupies one slot on the belt; duplicate IDs are
      collapsed to their first appearance
    - the belt wraps indefinitely, so k is reduced modulo the number of slots
    - an empty input list returns an empty list
    """
    try:
        payload = record["record_3"]
    except Exception:
        return []

    if payload is None:
        return []

    try:
        k = int(payload[0] or 0)
        values = list(payload[1] or [])
    except Exception:
        return []

    # Preserve first-seen order while collapsing duplicate IDs.
    slots = []
    seen = set()
    for item in values:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            # Fallback for unhashable entries; avoid duplicates by equality scan.
            if item in slots:
                continue
        slots.append(item)

    n = len(slots)
    if n == 0:
        return []

    k %= n
    return slots[-k:] + slots[:-k] if k else list(slots)
