def _scan_json_string_field(text, field):
    """
    Scan a tiny JSON object or array fragment for a string value.
    If field is None, returns the first string literal found.
    """
    import re
    pattern = r'"((?:\\.|[^"\\])*)"'
    matches = re.findall(pattern, text)
    if not matches:
        return None
    if field is None:
        return matches[0]
    # Field-specific scan
    key_pat = r'"' + re.escape(field) + r'"\s*:\s*"((?:\\.|[^"\\])*)"'
    m = re.search(key_pat, text)
    return m.group(1) if m else matches[0]


def _scan_json_number_field(text, field):
    """
    Scan a tiny JSON object or array fragment for an integer value.
    If field is None, returns the first signed integer found.
    """
    import re
    if field is None:
        m = re.search(r'-?\d+', text)
    else:
        m = re.search(r'"' + re.escape(field) + r'"\s*:\s*(-?\d+)', text)
    if not m:
        return None
    try:
        return int(m.group(1) if field else m.group(0))
    except ValueError:
        return None
